const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-136.325766, 69.954148]);
  const date1 = '2012-06-14';
  const date2 = '2012-07-05';

  // 2. Data Acquisition - Try Landsat 7
  let col1 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(point)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUD_COVER', 50));

  let col2 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(point)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUD_COVER', 50));

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`June 14 images: ${size1}, July 5 images: ${size2}`);

  // Try Landsat 5 as fallback
  if (size1 === 0 || size2 === 0) {
    col1 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(point)
      .filterDate(date1, ee.Date(date1).advance(1, 'day'))
      .filter(ee.Filter.lt('CLOUD_COVER', 50));

    col2 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(point)
      .filterDate(date2, ee.Date(date2).advance(1, 'day'))
      .filter(ee.Filter.lt('CLOUD_COVER', 50));

    const size1_l5 = await col1.size().getInfo();
    const size2_l5 = await col2.size().getInfo();

    console.log(`Landsat 5 - June 14: ${size1_l5}, July 5: ${size2_l5}`);

    if (size1_l5 === 0 || size2_l5 === 0) {
      console.log('No images found for one or both dates');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Calculate turbidity using Red/Green ratio
  function addTurbidity(image) {
    const red = image.select('SR_B3').multiply(0.0000275).add(-0.2);
    const green = image.select('SR_B2').multiply(0.0000275).add(-0.2);
    const turbidity = red.divide(green).rename('turbidity');
    return image.addBands(turbidity);
  }

  function maskClouds(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    return image.updateMask(qaMask);
  }

  const img1 = col1.map(maskClouds).map(addTurbidity).first();
  const img2 = col2.map(maskClouds).map(addTurbidity).first();

  // Check valid pixels
  const buffer = point.buffer(1000);

  const count1 = await img1.select('turbidity').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('turbidity').getInfo();

  const count2 = await img2.select('turbidity').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('turbidity').getInfo();

  console.log(`Valid pixels - June 14: ${count1}, July 5: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after cloud masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculate turbidity values
  const turb1 = await img1.select('turbidity').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('turbidity').getInfo();

  const turb2 = await img2.select('turbidity').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('turbidity').getInfo();

  console.log(`Turbidity - June 14: ${turb1}, July 5: ${turb2}`);

  // 5. Validation & Final Answer
  if (turb1 === null || turb2 === null || isNaN(turb1) || isNaN(turb2)) {
    console.log('Calculation failed - invalid turbidity values');
    console.log('<answer>C3</answer>');
    return;
  }

  if (turb1 < 0 || turb2 < 0 || turb1 > 10 || turb2 > 10) {
    console.log('Invalid turbidity range detected');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Change: ${((turb2 - turb1) / turb1 * 100).toFixed(2)}%`);

  if (turb2 > turb1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
